/* An AI site goes live in one step. A new server only function `switch_site_deployment(site, deployment, fields)`, called by an AI site's Publish (lib/sites/publish.ts): the old live deployment comes down and the new one goes up in one transaction, so a publish that fails part way changes nothing and the site that was live stays live, where before a failed second step could leave the site with no live deployment ("Site not found") until Publish was pressed again. It holds a lock per site while it runs, so two publishes of the same site wait for each other. It refuses a deployment that is not that site's. Only the service role can call it. Changes no existing row. Until it runs, Publish switches in two steps and puts the old version back if the second one fails. Needs the AI site tables (RUN_CREATOR_PAGE_AND_SITES, RUN_SITES_PUBLISHING); without them it is not created. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.site_deployments') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'site_deployments' AND column_name = 'is_live') THEN RAISE NOTICE 'site switch in one step: the AI site tables are not there yet.'; RETURN; END IF; EXECUTE $fn$CREATE OR REPLACE FUNCTION public.switch_site_deployment(p_site uuid, p_deployment uuid, p_fields jsonb) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $body$ BEGIN IF NOT EXISTS (SELECT 1 FROM public.site_deployments WHERE id = p_deployment AND site_id = p_site) THEN RAISE EXCEPTION 'switch: this deployment is not this site''s' USING ERRCODE = 'P0002'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('storelib-site-switch:' || p_site::text, 0)); UPDATE public.site_deployments SET is_live = false WHERE site_id = p_site AND is_live AND id <> p_deployment; UPDATE public.site_deployments SET is_live = true, status = 'ready', storage_prefix = COALESCE(p_fields->>'storage_prefix', storage_prefix), file_count = COALESCE((p_fields->>'file_count')::integer, file_count), bytes = COALESCE((p_fields->>'bytes')::bigint, bytes), published_at = COALESCE((p_fields->>'published_at')::timestamptz, now()), finished_at = COALESCE((p_fields->>'finished_at')::timestamptz, now()) WHERE id = p_deployment; RETURN true; END $body$$fn$; REVOKE ALL ON FUNCTION public.switch_site_deployment(uuid, uuid, jsonb) FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.switch_site_deployment(uuid, uuid, jsonb) TO service_role; END $do$;
notify pgrst, 'reload schema';
